class Solution:
    def maximumCoins(self, coins: List[List[int]], k: int) -> int:
        coins.sort()
        ans = 0
        for l, r, c in coins:
            for p in (r, l + k - 1):
                lo = p - k + 1
                tot = 0
                for cl, cr, cc in coins:
                    ov = min(cr, p) - max(cl, lo) + 1
                    if ov > 0:
                        tot += cc * ov
                ans = max(ans, tot)
        return ans

