import bisect
class Solution:
    def maximumCoins(self, coins: List[List[int]], k: int) -> int:
        coins.sort()
        n = len(coins)
        ls = [c[0] for c in coins]
        rs = [c[1] for c in coins]
        pref = [0] * (n + 1)
        for i, (l, r, c) in enumerate(coins):
            pref[i + 1] = pref[i] + c * (r - l + 1)
        def win(p):
            lo = p - k + 1
            i = bisect.bisect_left(rs, lo)
            if i == n or ls[i] > p:
                return 0
            tot = 0
            if ls[i] < lo:
                tot += coins[i][2] * (min(rs[i], p) - lo + 1)
                i += 1
            j = bisect.bisect_right(ls, p) - 1
            if j >= i:
                tot += pref[j + 1] - pref[i]
                if rs[j] > p:
                    tot -= coins[j][2] * (rs[j] - p)
            return tot
        ans = 0
        for l, r, c in coins:
            ans = max(ans, win(r), win(l + k - 1))
        return ans

