class Solution {
public:
    long long maximumCoins(vector<vector<int>>& coins, int k) {
        sort(coins.begin(), coins.end());
        int n = coins.size();
        vector<long long> ls(n), rs(n), pref(n + 1, 0);
        for (int i = 0; i < n; i++) {
            ls[i] = coins[i][0]; rs[i] = coins[i][1];
            pref[i + 1] = pref[i] + (long long)coins[i][2] * (coins[i][1] - coins[i][0] + 1);
        }
        auto win = [&](long long p) {
            long long lo = p - k + 1;
            int i = lower_bound(rs.begin(), rs.end(), lo) - rs.begin();
            if (i == n || ls[i] > p) return 0LL;
            long long tot = 0;
            if (ls[i] < lo) {
                tot += (long long)coins[i][2] * (min(rs[i], p) - lo + 1);
                i++;
            }
            int j = upper_bound(ls.begin(), ls.end(), p) - ls.begin() - 1;
            if (j >= i) {
                tot += pref[j + 1] - pref[i];
                if (rs[j] > p) tot -= (long long)coins[j][2] * (rs[j] - p);
            }
            return tot;
        };
        long long ans = 0;
        for (auto& c : coins)
            ans = max({ans, win(c[1]), win((long long)c[0] + k - 1)});
        return ans;
    }
};

