class Solution {
    public long maximumCoins(int[][] coins, int k) {
        Arrays.sort(coins, (a, b) -> Integer.compare(a[0], b[0]));
        int n = coins.length;
        long[] ls = new long[n], rs = new long[n], pref = new long[n + 1];
        for (int i = 0; i < n; i++) {
            ls[i] = coins[i][0]; rs[i] = coins[i][1];
            pref[i + 1] = pref[i] + (long) coins[i][2] * (coins[i][1] - coins[i][0] + 1);
        }
        java.util.function.LongUnaryOperator win = p -> {
            long lo = p - k + 1;
            int i = 0;
            while (i < n && rs[i] < lo) i++;
            if (i == n || ls[i] > p) return 0L;
            long tot = 0;
            if (ls[i] < lo) {
                tot += (long) coins[i][2] * (Math.min(rs[i], p) - lo + 1);
                i++;
            }
            int j = i;
            while (j + 1 < n && ls[j + 1] <= p) j++;
            if (j >= i) {
                tot += pref[j + 1] - pref[i];
                if (rs[j] > p) tot -= (long) coins[j][2] * (rs[j] - p);
            }
            return tot;
        };
        long ans = 0;
        for (int[] c : coins)
            ans = Math.max(ans, Math.max(win.applyAsLong(c[1]), win.applyAsLong((long) c[0] + k - 1)));
        return ans;
    }
}

