var maximumCoins = function(coins, k) {
    coins.sort((a, b) => a[0] - b[0]);
    const n = coins.length;
    const ls = coins.map(c => c[0]), rs = coins.map(c => c[1]);
    const pref = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++)
        pref[i + 1] = pref[i] + BigInt(coins[i][2]) * BigInt(coins[i][1] - coins[i][0] + 1);
    const lowBound = (arr, x) => {
        let lo = 0, hi = arr.length;
        while (lo < hi) { const m = (lo + hi) >> 1; if (arr[m] < x) lo = m + 1; else hi = m; }
        return lo;
    };
    const win = (p) => {
        const lo = p - k + 1;
        let i = lowBound(rs, lo);
        if (i === n || ls[i] > p) return 0n;
        let tot = 0n;
        if (ls[i] < lo) {
            tot += BigInt(coins[i][2]) * BigInt(Math.min(Number(rs[i]), Number(p)) - Number(lo) + 1);
            i++;
        }
        let j = lowBound(ls, Number(p) + 1) - 1;
        if (j >= i) {
            tot += pref[j + 1] - pref[i];
            if (rs[j] > p) tot -= BigInt(coins[j][2]) * BigInt(Number(rs[j]) - Number(p));
        }
        return tot;
    };
    let ans = 0n;
    for (const [l, r] of coins)
        ans = maxBig(ans, win(BigInt(r)), win(BigInt(l) + BigInt(k) - 1n));
    return Number(ans);
};
function maxBig(a, b, c) { return a > b ? (a > c ? a : c) : (b > c ? b : c); }
